/**
 * Reviewed pictures the assistant can show when someone asks to see
 * something (ADR-085). Every image is freely licensed on Wikimedia Commons;
 * the licence, author and source page were checked on 14 October 2026 and
 * are shown with the image. Pictures are matched to topics by code, never
 * chosen or generated by the AI, so a health image is always one a person
 * reviewed. To add one: find a freely licensed file on Commons, check its
 * licence on the file page, and add an entry with accurate alt text.
 */

export type Credit = {
  author: string;
  license: string;
  /** Licence deed; absent for public-domain works. */
  licenseUrl?: string;
  /** The Commons file page. */
  sourceUrl: string;
};

export type Visual = {
  id: string;
  title: string;
  /** Read by screen readers instead of the picture: what it shows, in plain words. */
  alt: string;
  /** Shown under the picture: what to notice. */
  caption: string;
  src: string;
  width: number;
  height: number;
  credit: Credit;
};

type Entry = Visual & {
  /** Matches the topic in the person's words or the recent conversation. */
  topic: RegExp;
  /** Higher first when several match. */
  rank: number;
};

