/** A Nigerian food photo (rank 1: shown only when that food is the topic). */
function food(
  id: string,
  topic: RegExp,
  title: string,
  alt: string,
  caption: string,
  src: string,
  width: number,
  height: number,
  author: string,
  file: string,
  licenseUrl = BY_SA_4,
  license = "CC BY-SA 4.0",
): Entry {
  return {
    id,
    rank: 1,
    topic,
    title,
    alt,
    caption,
    src,
    width,
    height,
    credit: {
      author,
      license,
      licenseUrl,
      sourceUrl: `https://commons.wikimedia.org/wiki/File:${file}`,
    },
  };
}
